 // handleStats returns detailed statistics
 func (hs *HEARTService) handleStats(w http.ResponseWriter, r *http.Request) {
 	w.Header().Set("Access-Control-Allow-Origin", "*")
 	w.Header().Set("Content-Type", "application/json")

 	hs.mu.RLock()
